/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventItemLocationPdsCWPickingLocationMaxQty extends UPSPricingAttributeInventItemLocation implements UPSIPricingAttribute
{
}

