public str getName()
{
    return fieldPName(InventItemLocation, pdsCWPickingLocationMaxQty);
}

public Set getAllowedValues()
{
    var                ret = new Set(Types::Real);
    InventItemLocation inventItemLocation;

    while select inventItemLocation
        group by pdsCWPickingLocationMaxQty
    {
        if (! ret.in(inventItemLocation.pdsCWPickingLocationMaxQty))
        {
            ret.add(inventItemLocation.pdsCWPickingLocationMaxQty);
        }
    }

    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventItemLocation, pdsCWPickingLocationMaxQty));
    qbr.value(queryValue(_value));
}
